idades: Felinos, Cães, Mamíferos, Sementes ou Aves de estimação.","escolha":{"n":1,"opcoes":["Felinos","Cães","Mamíferos","Sementes","Aves de estimação"]},"id":"amigo.VII.1","lacuna_schema":"escolha_n_de_m","observacao":"Revisão 2026.2: a alínea e) na página oficial é \"Aves de estimação\" (a 2026.1 trazia \"Aves\"). Nome de especialidade é identificador — copiado literalmente.","ordem":10,"tipo":"escolha_n_de_m","tipo_evidencia":"nenhuma"},{"codigo":"2","descricao_resumida":"Aprender e demonstrar um jeito de purificar a água e escrever um parágrafo sobre Jesus como a água da vida.","id":"amigo.VII.2","ordem":20,"tipo_evidencia":"foto"},{"codigo":"3","descricao_resumida":"Aprender a montar uma barraca e montá-la em local apropriado.","id":"amigo.VII.3","ordem":30,"tipo_evidencia":"foto"}]},{"codigo":"VIII","id":"amigo.VIII","nome":"Arte de Acampar","ordem":80,"requisitos":[{"codigo":"1","descricao_resumida":"Mostrar como cuidar de uma corda e fazer e explicar o uso de 14 nós: simples, cego, direito, cirurgião, lais de guia, lais de guia duplo, escota, catau, pescador, fateixa, volta do fiel, nó de gancho, volta da ribeira e ordinário.","id":"amigo.VIII.1","ordem":10,"tipo_evidencia":"nenhuma"},{"codigo":"2","descricao_resumida":"Completar a especialidade de Acampamento I.","id":"amigo.VIII.2","ordem":20,"tipo_evidencia":"nenhuma"},{"codigo":"3","descricao_resumida":"Apresentar 10 regras para uma caminhada e explicar o que fazer quando estiver perdido.","id":"amigo.VIII.3","ordem":30,"tipo_evidencia":"texto"},{"codigo":"4","descricao_resumida":"Aprender os sinais de pista e preparar uma pista de pelo menos 10 sinais para outros seguirem.","id":"amigo.VIII.4","ordem":40,"tipo_evidencia":"foto"}]},{"codigo":"IX","id":"amigo.IX","nome":"Estilo de Vida","ordem":90,"requisitos":[{"codigo":"1","descricao_resumida":"Completar 1 especialidade na área de Artes e habilidades manuais.","escolha":{"n":1},"id":"amigo.IX.1","lacuna_schema":"escolha_n_de_m","observacao":"Revisão 20